"""Wire ``on_knowledge_results`` / ``modify_knowledge_results`` after search."""

from __future__ import annotations

from typing import Any, List, Optional

import structlog

from rasa.core.information_retrieval import SearchResult, SearchResultList
from rasa.core.information_retrieval.models import Document
from rasa.mantle.hooks.constants import POINT_KNOWLEDGE_RESULTS
from rasa.mantle.hooks.payloads import KnowledgeResultsPayload
from rasa.mantle.hooks.registry import HookRegistry
from rasa.mantle.hooks.runner import run_modify, run_observers
from rasa.mantle.hooks.utils import hook_identity

# Public passage fields shared with the ``search_knowledge`` tool JSON shape.
_PASSAGE_TEXT = "text"
_PASSAGE_SCOPE = "scope"
_PASSAGE_SOURCE = "source"
_PASSAGE_SCORE = "score"

structlogger = structlog.get_logger()


def passages_from_results(
    results: SearchResultList,
    *,
    include_score: bool = True,
) -> List[dict[str, Any]]:
    """Project retrieved chunks into the public knowledge-results payload shape.

    Same fields as ``_format_search_results`` (``text``, ``scope``, ``source``).
    ``score`` is included only when requested and the store provided one —
    local FAISS typically leaves it unset.
    """
    passages: List[dict[str, Any]] = []
    for result in results.results:
        passage: dict[str, Any] = {
            _PASSAGE_TEXT: result.text,
            _PASSAGE_SCOPE: result.metadata.get(_PASSAGE_SCOPE),
            _PASSAGE_SOURCE: result.metadata.get(_PASSAGE_SOURCE),
        }
        if include_score and result.score is not None:
            passage[_PASSAGE_SCORE] = result.score
        passages.append(passage)
    return passages


def _passage_to_search_result(entry: Any) -> SearchResult:
    """Build one ``SearchResult`` from a hook-returned passage dict."""
    if not isinstance(entry, dict):
        raise TypeError("knowledge results passage must be a dict")

    metadata = {
        key: entry[key]
        for key in (_PASSAGE_SCOPE, _PASSAGE_SOURCE)
        if key in entry and entry[key] is not None
    }
    result = SearchResult.from_document(
        Document(text=str(entry.get(_PASSAGE_TEXT, "")), metadata=metadata)
    )
    score: Optional[Any] = entry.get(_PASSAGE_SCORE)
    return SearchResult(
        text=result.text,
        metadata=result.metadata,
        score=float(score) if score is not None else None,
    )


def results_from_passages(
    passages: List[Any],
    *,
    original: SearchResultList,
) -> SearchResultList:
    """Rebuild a ``SearchResultList`` from hook-returned passage dicts.

    Only the public passage keys are accepted (``text``, ``scope``, ``source``,
    ``score``). Construction goes through ``SearchResult.from_document``.
    """
    rebuilt = [_passage_to_search_result(entry) for entry in passages]
    return SearchResultList(results=rebuilt, metadata=dict(original.metadata))


async def apply_knowledge_results_hooks(
    registry: HookRegistry,
    *,
    query: str,
    results: SearchResultList,
) -> SearchResultList:
    """Run ``on_knowledge_results`` / ``modify_knowledge_results`` for one search.

    Observers fire-and-forget. The modify lane may filter, reorder, or empty
    ``passages``. This point has no control signals; unexpected crashes,
    timeouts, or invalid returns are fail-open and keep the original results.
    """
    # No registered hooks for this point — skip payload/runner setup.
    if (
        not registry.observers(POINT_KNOWLEDGE_RESULTS)
        and registry.modifier(POINT_KNOWLEDGE_RESULTS) is None
    ):
        return results

    try:
        sender_id, channel = hook_identity()
    except LookupError:
        # Live turns establish MessageTurnContext; missing context is misuse
        # (e.g. isolated unit tests). Keep the original results.
        structlogger.warning(
            "mantle.hooks.knowledge_results.skipped_no_turn_context",
        )
        return results

    payload = KnowledgeResultsPayload(
        sender_id=sender_id,
        channel=channel,
        query=query,
        passages=passages_from_results(results),
    )
    run_observers(registry, POINT_KNOWLEDGE_RESULTS, payload)
    result = await run_modify(registry, POINT_KNOWLEDGE_RESULTS, payload)

    modified = result.payload
    if not isinstance(modified, KnowledgeResultsPayload):
        return results

    try:
        return results_from_passages(modified.passages, original=results)
    except (TypeError, ValueError):
        return results
